light:
/* NL Design — custom token overrides. Generated by theme editor. Do not edit manually. */
:root {
  --color-primary-element: #154273 !important;
  --color-main-text: #222222 !important;
}
@media (prefers-color-scheme: dark) {
	body:not([data-theme-light]):not([data-theme-dark]):not([data-theme-light-highcontrast]):not([data-theme-dark-highcontrast]) {
	  --color-primary-element: dark(#154273) !important;
	  --color-main-text: #222222 !important;
	}
}
body[data-theme-dark],
body[data-themes*=dark] {
  --color-primary-element: dark(#154273) !important;
  --color-main-text: #222222 !important;
}

motion:
/* NL Design — custom token overrides. Generated by theme editor. Do not edit manually. */
:root {
  --animation-quick: 80ms !important;
  --nldesign-animation-quick: 80ms !important;
}
body:not([data-theme-reduced-motion]) {
  --animation-quick: 80ms !important;
}
@media (prefers-color-scheme: dark) {
	body:not([data-theme-light]):not([data-theme-dark]):not([data-theme-light-highcontrast]):not([data-theme-dark-highcontrast]) {
	  --animation-quick: dark(80ms) !important;
	}
}
body[data-theme-dark],
body[data-themes*=dark] {
  --animation-quick: dark(80ms) !important;
}

